function minMutation(startGene: string, endGene: string, bank: string[]): number {
  if (startGene === endGene) return 0;

  // Непосещённые допустимые гены; удаление из множества = пометка visited
  const unvisited = new Set(bank);
  if (!unvisited.has(endGene)) return -1; // цель недопустима — не дойдём никогда

  const letters = ['A', 'C', 'G', 'T'];
  let layer = [startGene];
  let steps = 0;

  // BFS: слой = все гены, достижимые ровно за steps мутаций
  while (layer.length) {
    steps++;
    const next: string[] = [];
    for (const gene of layer) {
      // Перебираем все одиночные мутации: позиция × новая буква
      for (let i = 0; i < gene.length; i++) {
        for (const ch of letters) {
          if (ch === gene[i]) continue;
          const mutated = gene.slice(0, i) + ch + gene.slice(i + 1);
          if (!unvisited.has(mutated)) continue; // недопустим или уже посещён
          if (mutated === endGene) return steps;
          unvisited.delete(mutated);
          next.push(mutated);
        }
      }
    }
    layer = next;
  }

  return -1;
}

// Время: O(B · L · 4 · L) — B генов в банке, для каждого L·4 мутаций, каждая строится за O(L)
// Память: O(B · L) — множество и очередь
